BEGIN;

CREATE TABLE IF NOT EXISTS public.current_office_assignments (
    person_id UUID NOT NULL REFERENCES public.people(id) ON DELETE CASCADE,
    role_key TEXT NOT NULL CHECK (role_key IN ('legislator', 'local_deputy', 'agency_head')),
    office_label TEXT NOT NULL,
    region_name TEXT,
    source_name TEXT NOT NULL,
    source_url TEXT,
    observed_at DATE NOT NULL,
    source_kind TEXT NOT NULL,
    is_current BOOLEAN NOT NULL DEFAULT TRUE,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (person_id, role_key)
);

ALTER TABLE public.current_office_assignments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.current_office_assignments FROM PUBLIC, anon, authenticated;

    person_id, role_key, office_label, region_name, source_name, source_url,
    observed_at, source_kind
)
SELECT
    person.person_id,
    person.list_role,
    person.position,
    person.district,
    '各縣市政府首長名錄（既有官方匯入）',
    NULL,
    DATE '2026-06-30',
    'release_snapshot'
FROM public.public_people_list_cached person
WHERE person.list_role IN ('local_deputy', 'agency_head')
  AND person.list_status = 'other'
  AND NULLIF(BTRIM(person.position), '') IS NOT NULL
  AND NULLIF(BTRIM(person.district), '') IS NOT NULL
ON CONFLICT (person_id, role_key) DO UPDATE SET
    office_label = EXCLUDED.office_label,
    region_name = EXCLUDED.region_name,
    source_name = EXCLUDED.source_name,
    source_url = EXCLUDED.source_url,
    observed_at = EXCLUDED.observed_at,
    source_kind = EXCLUDED.source_kind,
    is_current = TRUE,
    updated_at = NOW();

    person_id, role_key, office_label, region_name, source_name, source_url,
    observed_at, source_kind
)
