    is_current = TRUE,
    updated_at = NOW();

CREATE TABLE IF NOT EXISTS published.person_demographics (
    person_id UUID PRIMARY KEY REFERENCES public.people(id) ON DELETE CASCADE,
    birth_date DATE NOT NULL,
    observed_at DATE NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

REVOKE ALL ON TABLE published.person_demographics FROM PUBLIC, anon, authenticated;

ON CONFLICT (person_id) DO UPDATE SET
    birth_date = EXCLUDED.birth_date,
    observed_at = EXCLUDED.observed_at,
    updated_at = NOW();

CREATE OR REPLACE FUNCTION published.refresh_person_demographics()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, published
AS $$
BEGIN
    WITH RECURSIVE published_people AS (
        SELECT person_id FROM published.people
    ),
    member_ids(canonical_person_id, source_person_id, path, depth) AS (
        SELECT person_id, person_id, ARRAY[person_id], 0 FROM published_people
        UNION ALL
        SELECT
            member.canonical_person_id,
            decision.duplicate_person_id,
            member.path || decision.duplicate_person_id,
            member.depth + 1
        FROM member_ids member
        JOIN public.person_merge_decisions decision
          ON decision.canonical_person_id = member.source_person_id
         AND decision.status = 'verified'
        WHERE member.depth < 20
          AND NOT decision.duplicate_person_id = ANY (member.path)
    ),
    resolved AS (
        SELECT
            member.canonical_person_id AS person_id,
            MIN(claim.claim_value::DATE) AS birth_date
        FROM member_ids member
        JOIN public.person_claims claim
          ON claim.person_id = member.source_person_id
         AND claim.claim_type = 'birth_date'
         AND claim.review_status = 'verified'
         AND claim.visibility = 'public'
         AND claim.is_public = TRUE
         AND claim.claim_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
         AND pg_input_is_valid(claim.claim_value, 'date')
        GROUP BY member.canonical_person_id
        HAVING COUNT(DISTINCT claim.claim_value::DATE) = 1
    )
    SELECT person_id, birth_date, CURRENT_DATE
    FROM resolved
    ON CONFLICT (person_id) DO UPDATE SET
        birth_date = EXCLUDED.birth_date,
        observed_at = EXCLUDED.observed_at,
        updated_at = NOW();
END;
$$;

REVOKE ALL ON FUNCTION published.refresh_person_demographics() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION published.refresh_person_demographics() TO service_role;

CREATE OR REPLACE FUNCTION public.refresh_current_office_assignments()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, published
AS $$
BEGIN
        person_id, role_key, office_label, region_name, source_name, source_url,
        observed_at, source_kind
    )
    SELECT DISTINCT ON (canonical_map.canonical_person_id, role.role_key)
        canonical_map.canonical_person_id,
        role.role_key,
        source.position,
        source.district,
        source.source_name,
        source.source_url,
        COALESCE(source.updated_at::DATE, CURRENT_DATE),
        'official_source'
    FROM public.source_people source
    JOIN public.person_identity_matches identity_match
      ON identity_match.source_person_id = source.id
     AND identity_match.match_status IN ('auto_matched', 'probable_match')
    JOIN public.person_canonical_map canonical_map
      ON canonical_map.person_id = identity_match.person_id
    CROSS JOIN LATERAL (
        SELECT CASE
            WHEN source.position ~ '(副市長|副縣長|副縣市長)' THEN 'local_deputy'
            WHEN source.position ~ '(局長|處長|主任委員)' AND source.district IS NOT NULL THEN 'agency_head'
            WHEN source.position ~ '(立法委員|立法院院長|立法院副院長)' THEN 'legislator'
            ELSE NULL
        END AS role_key
    ) role
    WHERE source.source_type = 'official_officeholder'
      AND source.is_public = TRUE
      AND source.source_payload ->> 'isCurrent' = 'true'
      AND role.role_key IS NOT NULL
    ORDER BY
        canonical_map.canonical_person_id,
        role.role_key,
        source.updated_at DESC,
        source.position
    ON CONFLICT (person_id, role_key) DO UPDATE SET
        office_label = EXCLUDED.office_label,
        region_name = EXCLUDED.region_name,
        source_name = EXCLUDED.source_name,
        source_url = EXCLUDED.source_url,
        observed_at = EXCLUDED.observed_at,
        source_kind = EXCLUDED.source_kind,
        is_current = TRUE,
        updated_at = NOW();
END;
$$;

REVOKE ALL ON FUNCTION public.refresh_current_office_assignments() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_current_office_assignments() TO service_role;

CREATE OR REPLACE VIEW public_people_list AS
WITH current_assignment AS (
    SELECT DISTINCT ON (assignment.person_id)
        assignment.person_id,
        assignment.office_label,
        assignment.region_name,
        assignment.role_key
    FROM public.current_office_assignments assignment
    WHERE assignment.is_current = TRUE
    ORDER BY
        assignment.person_id,
        CASE assignment.role_key
            WHEN 'legislator' THEN 0
            WHEN 'local_deputy' THEN 1
            WHEN 'agency_head' THEN 2
            ELSE 9
        END,
        assignment.observed_at DESC,
        assignment.office_label
),
candidate_summary AS (
    SELECT
        person_id,
        TRUE AS has_candidate_history,
        BOOL_OR(
            election_year >= EXTRACT(YEAR FROM CURRENT_DATE)::INT
            AND candidacy_status = 'party_nominee'
        ) AS has_upcoming_candidate,
        (
            ARRAY_AGG(
                race_title
                ORDER BY election_year DESC NULLS LAST, candidate_updated_at DESC NULLS LAST
            ) FILTER (
                WHERE election_year >= EXTRACT(YEAR FROM CURRENT_DATE)::INT
                  AND candidacy_status = 'party_nominee'
            )
        )[1] AS upcoming_candidate_race_title,
        BOOL_OR(
            COALESCE(person_position, '') ~ '(村里|村長|里長|代表)'
            OR COALESCE(race_title, '') ~ '(村里|村長|里長|代表)'
        ) AS has_grassroots_history
    FROM public_candidates
    GROUP BY person_id
),
classified AS (
    SELECT
        people.*,
        current_assignment.office_label AS assignment_office_label,
        current_assignment.region_name AS assignment_region_name,
        COALESCE(
            current_assignment.office_label,
            people.current_office_label,
            people.upcoming_candidate_label,
            candidate_summary.upcoming_candidate_race_title,
            people.position,
            ''
        ) AS list_position,
        COALESCE(candidate_summary.has_candidate_history, FALSE) AS has_candidate_history,
        COALESCE(candidate_summary.has_upcoming_candidate, FALSE) AS has_upcoming_candidate,
        (
            COALESCE(
                current_assignment.office_label,
                people.current_office_label,
                people.upcoming_candidate_label,
                candidate_summary.upcoming_candidate_race_title,
                people.position,
                ''
            ) ~ '(村里|村長|里長|代表)'
            OR COALESCE(candidate_summary.has_grassroots_history, FALSE)
        ) AS list_is_grassroots
    FROM public_people people
    LEFT JOIN current_assignment ON current_assignment.person_id = people.person_id
    LEFT JOIN candidate_summary ON candidate_summary.person_id = people.person_id
),
role_classified AS (
    SELECT
        classified.*,
        CASE
            WHEN list_position LIKE '%副總統%' THEN 'vice_president'
            WHEN list_position LIKE '%總統%' THEN 'president'
            WHEN list_position ~ '(立法委員|立委)' THEN 'legislator'
            WHEN list_position LIKE '%議員%' THEN 'councilor'
            WHEN list_position ~ '(副市長|副縣長|副縣市長)' THEN 'local_deputy'
            WHEN list_position ~ '(市長|縣長)' THEN 'local_chief'
            WHEN list_position ~ '(局長|處長|主任委員)' THEN 'agency_head'
            WHEN list_position ~ '(黨主席|主席|秘書長)' THEN 'party_officer'
            WHEN list_position LIKE '%候選人%' THEN 'candidate'
            ELSE 'other'
        END AS list_role
    FROM classified
),
status_classified AS (
    SELECT
        role_classified.*,
        CASE
            WHEN assignment_office_label IS NOT NULL OR current_office_label IS NOT NULL THEN 'current'
            WHEN upcoming_candidate_label IS NOT NULL OR has_upcoming_candidate THEN 'candidate'
            WHEN has_candidate_history THEN 'former'
            ELSE 'other'
        END AS list_status
    FROM role_classified
)
SELECT
    person_id,
    name,
    alias,
    party,
    position,
    election_year,
    COALESCE(assignment_region_name, district) AS district,
    updated_at,
    primary_photo_url,
    primary_photo_thumbnail_url,
    photo_source_name,
    photo_source_url,
    photo_license_type,
    photo_license_url,
    photo_attribution,
    gender,
    education,
    experience,
    COALESCE(assignment_office_label, current_office_label) AS current_office_label,
    upcoming_candidate_label,
    list_role,
    list_status,
    list_is_grassroots,
    CASE list_status
        WHEN 'current' THEN 0
        WHEN 'candidate' THEN 1
        WHEN 'former' THEN 2
        ELSE 3
    END AS list_status_order,
    CASE list_role
        WHEN 'president' THEN 0
        WHEN 'vice_president' THEN 1
        WHEN 'legislator' THEN 2
        WHEN 'local_chief' THEN 3
        WHEN 'local_deputy' THEN 4
        WHEN 'councilor' THEN 5
        WHEN 'party_officer' THEN 6
        WHEN 'agency_head' THEN 6
        WHEN 'candidate' THEN 7
        ELSE 8
    END AS list_role_order
FROM status_classified;

REVOKE ALL ON public_people_list FROM PUBLIC;
GRANT SELECT ON public_people_list TO anon, authenticated;

COMMENT ON VIEW public_people_list IS
    'Public person list projection with evidence-based current status and party-nominee candidate classification.';

SELECT public.refresh_public_people_list_cached();


CREATE OR REPLACE FUNCTION published.party_people_statistics(
    p_party_name TEXT
)
RETURNS TABLE (
    party_name TEXT,
    dimension_key TEXT,
    bucket_key TEXT,
    people_count INTEGER,
    total_people INTEGER
)
LANGUAGE SQL
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public, published
AS $$
    WITH RECURSIVE normalized_party AS (
        SELECT public.canonical_party_name(NULLIF(BTRIM(p_party_name), '')) AS party_name
    ),
    party_people AS MATERIALIZED (
        SELECT
            person.person_id,
            person.gender,
            person.education,
            person.list_status
        FROM published.people person
        CROSS JOIN normalized_party party
        WHERE party.party_name IS NOT NULL
          AND NULLIF(BTRIM(person.party), '') = party.party_name
    ),
    current_party_officers AS MATERIALIZED (
        SELECT DISTINCT officer.person_id
        FROM published.party_officers officer
        CROSS JOIN normalized_party party
        WHERE officer.party_name = party.party_name
    ),
    party_member_ids(canonical_person_id, source_person_id, path, depth) AS (
        SELECT
            person.person_id,
            person.person_id,
            ARRAY[person.person_id],
            0
        FROM party_people person

        UNION ALL

        SELECT
            member.canonical_person_id,
            decision.duplicate_person_id,
            member.path || decision.duplicate_person_id,
            member.depth + 1
        FROM party_member_ids member
        JOIN public.person_merge_decisions decision
          ON decision.canonical_person_id = member.source_person_id
         AND decision.status = 'verified'
        WHERE member.depth < 20
          AND NOT decision.duplicate_person_id = ANY (member.path)
    ),
    resolved_birth_dates AS (
        SELECT person_id, birth_date
        FROM published.person_demographics
    ),
    normalized_people AS MATERIALIZED (
        SELECT
            person.person_id,
            CASE
                WHEN person.gender = 'male' THEN 'male'
                WHEN person.gender = 'female' THEN 'female'
                ELSE 'unknown'
            END AS gender_key,
            CASE
                WHEN person.education IS NULL OR BTRIM(person.education) = '' THEN 'unknown'
                WHEN LOWER(REGEXP_REPLACE(person.education, '[[:space:];；,，、()（）\[\]．._-]+', '', 'g')) ~ '高中職?以下' THEN 'secondary_or_below'
                WHEN LOWER(REGEXP_REPLACE(person.education, '[[:space:];；,，、()（）\[\]．._-]+', '', 'g')) IN ('其他', '不詳', '未知', '無資料') THEN 'other'
                WHEN LOWER(REGEXP_REPLACE(person.education, '[[:space:];；,，、()（）\[\]．._-]+', '', 'g')) IN ('大專', '大專學歷') THEN 'tertiary_unspecified'
                WHEN LOWER(person.education) ~ 'phd|doctorate' OR person.education ~ '博士' THEN 'doctorate'
                WHEN LOWER(person.education) ~ 'master|emba|mba' OR person.education ~ '碩士|研究所' THEN 'master'
                WHEN LOWER(person.education) ~ 'university|college|bachelor' OR person.education ~ '大學|學院|學士|學系' THEN 'university'
                WHEN person.education ~ '專科|工專|商專|醫專|護專|警專|五專|二專' THEN 'junior_college'
                WHEN person.education ~ '高中|高職|高級中學|職校' THEN 'high_school'
                WHEN person.education ~ '國中|國民中學|初中|國小|國民小學|小學' THEN 'secondary_or_below'
                ELSE 'other'
            END AS education_key,
            CASE
                WHEN birth.birth_date IS NULL THEN 'unknown'
                WHEN DATE_PART('year', AGE(CURRENT_DATE, birth.birth_date)) >= 0
                 AND DATE_PART('year', AGE(CURRENT_DATE, birth.birth_date)) < 40
                    THEN 'under_40'
                WHEN DATE_PART('year', AGE(CURRENT_DATE, birth.birth_date)) < 50 THEN '40_49'
                WHEN DATE_PART('year', AGE(CURRENT_DATE, birth.birth_date)) < 60 THEN '50_59'
                WHEN DATE_PART('year', AGE(CURRENT_DATE, birth.birth_date)) <= 120 THEN '60_plus'
                ELSE 'unknown'
            END AS age_key,
            (
                person.list_status = 'current'
                OR officer.person_id IS NOT NULL
            ) AS is_current
        FROM party_people person
        LEFT JOIN resolved_birth_dates birth ON birth.person_id = person.person_id
        LEFT JOIN current_party_officers officer ON officer.person_id = person.person_id
    ),
    totals AS (
        SELECT
            COUNT(*)::INTEGER AS total_people,
            COUNT(*) FILTER (WHERE is_current)::INTEGER AS current_people,
            COUNT(*) FILTER (WHERE NOT is_current)::INTEGER AS not_current_people,
            COUNT(*) FILTER (WHERE gender_key = 'male')::INTEGER AS male_people,
            COUNT(*) FILTER (WHERE gender_key = 'female')::INTEGER AS female_people,
            COUNT(*) FILTER (WHERE gender_key = 'unknown')::INTEGER AS unknown_gender_people,
            COUNT(*) FILTER (WHERE age_key = 'under_40')::INTEGER AS under_40_people,
            COUNT(*) FILTER (WHERE age_key = '40_49')::INTEGER AS age_40_49_people,
            COUNT(*) FILTER (WHERE age_key = '50_59')::INTEGER AS age_50_59_people,
            COUNT(*) FILTER (WHERE age_key = '60_plus')::INTEGER AS age_60_plus_people,
            COUNT(*) FILTER (WHERE age_key = 'unknown')::INTEGER AS unknown_age_people,
            COUNT(*) FILTER (WHERE education_key = 'doctorate')::INTEGER AS doctorate_people,
            COUNT(*) FILTER (WHERE education_key = 'master')::INTEGER AS master_people,
            COUNT(*) FILTER (WHERE education_key = 'university')::INTEGER AS university_people,
            COUNT(*) FILTER (WHERE education_key = 'tertiary_unspecified')::INTEGER AS tertiary_unspecified_people,
            COUNT(*) FILTER (WHERE education_key = 'junior_college')::INTEGER AS junior_college_people,
            COUNT(*) FILTER (WHERE education_key = 'high_school')::INTEGER AS high_school_people,
            COUNT(*) FILTER (WHERE education_key = 'secondary_or_below')::INTEGER AS secondary_or_below_people,
            COUNT(*) FILTER (WHERE education_key = 'other')::INTEGER AS other_education_people,
            COUNT(*) FILTER (WHERE education_key = 'unknown')::INTEGER AS unknown_education_people
        FROM normalized_people
    )
    SELECT
        party.party_name,
        bucket.dimension_key,
        bucket.bucket_key,
        bucket.people_count,
        totals.total_people
    FROM normalized_party party
    CROSS JOIN totals
    CROSS JOIN LATERAL (
        VALUES
            ('current_status', 'current', totals.current_people),
            ('current_status', 'not_current', totals.not_current_people),
            ('gender', 'male', totals.male_people),
            ('gender', 'female', totals.female_people),
            ('gender', 'unknown', totals.unknown_gender_people),
            ('age', 'under_40', totals.under_40_people),
            ('age', '40_49', totals.age_40_49_people),
            ('age', '50_59', totals.age_50_59_people),
            ('age', '60_plus', totals.age_60_plus_people),
            ('age', 'unknown', totals.unknown_age_people),
            ('education', 'doctorate', totals.doctorate_people),
            ('education', 'master', totals.master_people),
            ('education', 'university', totals.university_people),
            ('education', 'tertiary_unspecified', totals.tertiary_unspecified_people),
            ('education', 'junior_college', totals.junior_college_people),
            ('education', 'high_school', totals.high_school_people),
            ('education', 'secondary_or_below', totals.secondary_or_below_people),
            ('education', 'other', totals.other_education_people),
            ('education', 'unknown', totals.unknown_education_people)
    ) AS bucket(dimension_key, bucket_key, people_count);
$$;

ALTER FUNCTION published.promote(UUID)
    RENAME TO promote_core_without_runtime_snapshots;

REVOKE ALL ON FUNCTION published.promote_core_without_runtime_snapshots(UUID)
FROM PUBLIC, anon, authenticated, service_role;

CREATE FUNCTION published.promote(p_source_sync_run_id UUID DEFAULT NULL)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, published
AS $$
DECLARE
    release_id UUID;
BEGIN
    PERFORM public.refresh_current_office_assignments();
    PERFORM public.refresh_public_people_list_cached();
    release_id := published.promote_core_without_runtime_snapshots(p_source_sync_run_id);
    PERFORM published.refresh_person_demographics();
    RETURN release_id;
END;
$$;

REVOKE ALL ON FUNCTION published.promote(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION published.promote(UUID) TO service_role;

COMMENT ON FUNCTION published.promote(UUID) IS
    'Refreshes compact runtime office and demographic snapshots around the published read-layer promotion.';



SELECT public.refresh_public_people_list_cached();
SELECT published.promote(NULL);

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM published.people_directory WHERE list_role = 'legislator' AND list_status = 'current') <> 113 THEN
        RAISE EXCEPTION 'Current legislator runtime snapshot must contain 113 people';
    END IF;
    IF (SELECT COUNT(*) FROM published.people_directory WHERE list_role = 'local_deputy' AND list_status = 'current') = 0 THEN
        RAISE EXCEPTION 'Current local deputy runtime snapshot is empty';
    END IF;
    IF (SELECT COUNT(*) FROM published.people_directory WHERE list_role = 'agency_head' AND list_status = 'current') = 0 THEN
        RAISE EXCEPTION 'Current agency-head runtime snapshot is empty';
    END IF;
    IF (SELECT COUNT(*) FROM published.person_demographics) < 1000 THEN
        RAISE EXCEPTION 'Published person demographic snapshot is unexpectedly empty';
    END IF;
END;
$$;

NOTIFY pgrst, 'reload schema';

COMMIT;
